CREATE OR REPLACE VIEW `vwcoordinatori` AS select distinct `v`.`denominazione_riferimento` AS `denominazione_riferimento`,`p`.`denominazione_riferimento` AS `coordinato` from (`provvigioni` `p` join `vwpraticacoordinata` `v` on((`v`.`id_pratica` = `p`.`id_pratica`))) where ((`p`.`denominazione_riferimento` <> `v`.`denominazione_riferimento`) and (`p`.`tipo` = 'Agente')) order by `v`.`denominazione_riferimento`
